using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
internal static class StudioOrientationLabelValidation{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static AnimationStudioWindow controller;static MashBoxStudioViewport view;static StudioModelEditor editor;static StudioModelDocument doc;static double next;static int phase;
 static string Out(string s)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../orientation-label-"+s));
 [InitializeOnLoadMethod]static void Boot(){if(Application.dataPath.EndsWith("ThemeIsolationProject/Assets")&&File.Exists(Out("request.txt")))EditorApplication.delayCall+=Run;}
 static object Field(string n)=>typeof(StudioModelEditor).GetField(n,F).GetValue(editor);
 static void Run(){try{File.Delete(Out("request.txt"));doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var faces);doc.nodes.Add(new StudioModelDocument.Node{name="Label cube",mesh=mesh,cutPolygons=faces,cutTriangles=mesh.triangles});controller=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(controller,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(controller,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(controller,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==controller);editor=(StudioModelEditor)typeof(AnimationStudioWindow).GetField("modelEditor",F).GetValue(controller);editor.SelectObject(0);editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Object);editor.ActivateTool(Tool.Move);editor.SetToolbarComponentAxes();StudioSettings.Current.showTransformOrientationLabel=true;view.position=new Rect(50,50,1200,850);view.LookAtDirect(Vector3.zero,Quaternion.Euler(8,150,0),2);view.Repaint();next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;}catch(Exception e){File.WriteAllText(Out("result.txt"),e.ToString());}}
 static void Capture(string name){var parent=typeof(EditorWindow).GetField("m_Parent",F).GetValue(view);var rt=new RenderTexture((int)view.position.width,(int)view.position.height,0);rt.Create();var old=RenderTexture.active;try{parent.GetType().GetMethod("GrabPixels",F).Invoke(parent,new object[]{rt,new Rect(Vector2.zero,view.position.size)});RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(Out(name+".png"),image.EncodeToPNG());Object.DestroyImmediate(image);}finally{RenderTexture.active=old;Object.DestroyImmediate(rt);}}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;try{if(phase==0){Capture("enabled");File.WriteAllText(Out("result.txt"),"anchor valid="+Field("transformOrientationLabelVisible")+" cameraGUI="+Field("transformOrientationGuiPoint")+" view="+view.position+" canvas="+view.ModelCanvasRect+" cameraRect="+view.camera.pixelRect+" projected="+view.camera.WorldToScreenPoint(Vector3.zero)+" left="+Field("transformOrientationLabelOnLeft")+" orientation="+editor.ToolbarOrientationLabel);StudioSettings.Current.showTransformOrientationLabel=false;view.Repaint();phase++;next=EditorApplication.timeSinceStartup+.5f;}else{Capture("disabled");StudioSettings.Current.showTransformOrientationLabel=true;view.Repaint();EditorApplication.update-=Tick;File.AppendAllText(Out("result.txt"),"\nCaptured enabled and disabled; native visual comparison required.");}}catch(Exception e){EditorApplication.update-=Tick;File.AppendAllText(Out("result.txt"),e.ToString());}}
}
